GPL.add(planeFill);
registerInteractive(planeFill, {
  title: 'Image plane (Z = f)',
  tooltip: 'Image plane Z = f',
  body: 'The retina / sensor, at focal distance f = 2.5 from O. Every green ray leaves a single image point where it crosses this plane.'
