  new THREE.Vector3(PLN.x0, PLN.y0, F), new THREE.Vector3(PLN.x1, PLN.y0, F),
  new THREE.Vector3(PLN.x1, PLN.y1, F), new THREE.Vector3(PLN.x0, PLN.y1, F)
