for (let i = 0; i < NB - 1; i++) {
  const a = makeArrow(0.012, 0.045, 0.13, COL.red); GPL.add(a); imgArrow.push(a);
}
for (let k = 0; k < NB + 1; k++) {
  const a = makeArrow(0.05, 0.17, 0.55, COL.red); G3D.add(a); arr3d.push(a);
}
registerInteractive(arr3d[3], {
  title: '3D velocity V (constant)',
  tooltip: 'Constant 3D velocity V',
  body: 'All of these red arrows have exactly the same length: the bird translates with constant velocity V. Only the projected steps on the image plane shrink.'
