/* ── V direction ray, its arrow, drag handle ──────────────────────────────── */
const dirRay = makeTube(0.018, COL.green, 1); G3D.add(dirRay);
const dirArrow = makeArrow(0.06, 0.19, 0.6, COL.red); G3D.add(dirArrow);
const handle = new THREE.Mesh(new THREE.SphereGeometry(0.18, 20, 16),
  new THREE.MeshBasicMaterial({ color: COL.orange }));
G3D.add(handle);
registerInteractive(handle, {
  title: 'Drag: translation direction',
  tooltip: 'Drag to change the direction of V',
  body: 'This handle rotates the direction of V while keeping its magnitude. The vanishing point jumps to the image of the new direction, and the whole family of projected positions re-converges there.'
