/* ── current (slider-driven) bird ─────────────────────────────────────────── */
const birdCur = makeBird(COL.orange); birdCur.scale.setScalar(BIRD_W); G3D.add(birdCur);
const rayCur = makeTube(0.026, COL.orange, 1); G3D.add(rayCur);
const arrCur3d = makeArrow(0.055, 0.18, 0.55, COL.orange); G3D.add(arrCur3d);
const birdCurP = makeBird(COL.orange); GPL.add(birdCurP);
const arrCurImg = makeArrow(0.017, 0.058, 0.15, COL.orange); GPL.add(arrCurImg);

/* ── labels ───────────────────────────────────────────────────────────────── */
const labO = addLabel('O', new THREE.Vector3(), { bold: true, fontSize: '17px', offset: [-16, 18] });
const labV3 = addLabel('V', new THREE.Vector3(), { bold: true, fontSize: '17px', offset: [0, -2] });
const labVray = addLabel('V', new THREE.Vector3(), { bold: true, fontSize: '17px', offset: [0, -2] });
