function setLabel(entry, pos, show) { entry.pos.copy(show ? pos : HIDDEN); }

/* ── geometry update pass ─────────────────────────────────────────────────── */
let tState = 0;
const TMAX = 5;   // slider t in [0,1] → t_world in [0,5]; step arrow uses Δt = 1
let viewMode = '3D scene';

function P(t) { return new THREE.Vector3(P0.x + V.x * t, P0.y + V.y * t, P0.z + V.z * t); }
function proj(p) { return new THREE.Vector3(F * p.x / p.z, F * p.y / p.z, F + 0.006); }

const readoutEl = document.getElementById('readout');

function update() {
