  const imgStep = Math.hypot(qn.x - qc.x, qn.y - qc.y);
  readoutEl.textContent =
    't        = ' + tw.toFixed(2) + '\n' +
    'depth Z  = ' + pc.z.toFixed(2) + '\n' +
    '3D step  = ' + VMAG.toFixed(3) + '   (constant)\n' +
    'img step = ' + imgStep.toFixed(3) + '\n' +
    'VP       = (' + vp.x.toFixed(2) + ', ' + vp.y.toFixed(2) + ')';
}
update();

/* ── camera views ─────────────────────────────────────────────────────────── */
function applyCamera() {
  if (viewMode === '3D scene') {
    setCameraView({
      projection: 'perspective',
      azimuthDeg: 145, elevationDeg: -18, rollDeg: 0,
      heightFraction: 0.62
    });
  } else {
    setCameraView({
      projection: 'perspective',
      azimuthDeg: -90, elevationDeg: 0, rollDeg: 0,
      target: [(PLN.x0 + PLN.x1) / 2, (PLN.y0 + PLN.y1) / 2, F],
      heightFraction: 0.86
    });
  }
}
applyCamera();

const btn3D = document.getElementById('btnView3D');
const btnImg = document.getElementById('btnViewImg');
function setViewMode(m, refit) {
  if (m === viewMode && refit !== true) { return; }
  viewMode = m;
  btn3D.classList.toggle('active', m === '3D scene');
  btnImg.classList.toggle('active', m !== '3D scene');
  if (m === '3D scene') { if (!G3D.parent) scene.add(G3D); }
  else { if (G3D.parent) scene.remove(G3D); }
  update();
  applyCamera();
}
btn3D.addEventListener('click', () => setViewMode('3D scene'));
btnImg.addEventListener('click', () => setViewMode('Camera image plane'));

/* ── slider / animation ───────────────────────────────────────────────────── */
const slider = document.getElementById('sTime');
const btnFly = document.getElementById('btnFly');
let playing = false, tweening = false, twFrom = 0, twTo = 0, twStart = 0;

slider.addEventListener('input', () => {
  tState = parseFloat(slider.value);
  playing = false; tweening = false;
  btnFly.textContent = '▶ Fly (constant V)';
  btnFly.classList.remove('active');
  update();
});
btnFly.addEventListener('click', () => {
  playing = !playing;
  tweening = false;
  btnFly.textContent = playing ? '❚❚ Pause' : '▶ Fly (constant V)';
  btnFly.classList.toggle('active', playing);
});

/* ── drag the direction of V ──────────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
let dragging = false;
function ptr(e) {
  const r = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  dragPtr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
function setVfromPoint(p) {
  let z = p.z; if (z < 0.05) z = 0.05;
  let rx = p.x / z, ry = p.y / z;
  rx = THREE.MathUtils.clamp(rx, -0.52, 0.66);
  ry = THREE.MathUtils.clamp(ry, -0.42, 0.52);
  V.set(rx, ry, 1).normalize().multiplyScalar(VMAG);
  update();
}
canvas.addEventListener('pointerdown', (e) => {
  if (viewMode !== '3D scene') return;
  ptr(e); dragRay.setFromCamera(dragPtr, camera);
  if (dragRay.intersectObject(handle, true).length) {
    dragging = true;
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  ptr(e); dragRay.setFromCamera(dragPtr, camera);
  const sph = new THREE.Sphere(O_PT.clone(), RAY_L);
  const p = new THREE.Vector3();
  if (!dragRay.ray.intersectSphere(sph, p)) {
    dragRay.ray.closestPointToPoint(O_PT, p);
    if (p.length() < 1e-6) return;
    p.normalize().multiplyScalar(RAY_L);
  }
  setVfromPoint(p);
});
window.addEventListener('pointerup', () => {
  if (!dragging) return;
  dragging = false;
  controls.enabled = true;
  canvas.style.cursor = 'default';
});
document.getElementById('btnResetV').addEventListener('click', () => {
  V.copy(V0); update();
});

/* ── guided demo ──────────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'Bird near the camera',
    narration: 'The bird starts close and to the left. Its projection lands far from the vanishing point, and one step of 3D motion sweeps a long arrow across the image plane.',
    state: { viewMode: '3D scene', flightTime: 0.05 }
  },
  {
    title: 'Same V, smaller image motion',
    narration: 'The red 3D arrows stay equal in length — the bird never changes speed — but the projected bird\u2019s steps on the image plane are already noticeably shorter.',
    state: { viewMode: '3D scene', flightTime: 0.45 }
  },
  {
    title: 'Converging on the vanishing point',
    narration: 'Far away, successive projections crowd together next to the black dot. The image velocity approaches zero at the vanishing point of the motion direction.',
    state: { viewMode: '3D scene', flightTime: 0.95 }
  },
  {
    title: 'What the camera sees',
    narration: 'Switching to the image plane, the whole sequence is a straight 2D track with arrows shrinking toward the focus of expansion — the point that reveals which way the bird is translating.',
    state: { viewMode: 'Camera image plane', flightTime: 0.95 }
  }
];
let stepIdx = -1;
const stepTitleEl = document.getElementById('stepTitle');
const stepTextEl = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  playing = false;
  btnFly.textContent = '▶ Fly (constant V)';
  btnFly.classList.remove('active');
  setViewMode(s.state.viewMode);
  twFrom = tState; twTo = s.state.flightTime; twStart = performance.now(); tweening = true;
  stepTitleEl.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.title;
  stepTextEl.textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
stepTitleEl.textContent = 'Press “Next ▶” to start';
stepTextEl.textContent = 'A static camera at O watches a bird translate with constant velocity V.';

/* ── per-frame state loop (billboarding + time) ───────────────────────────── */
let lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.06, (now - lastT) / 1000);
  lastT = now;
  let dirty = false;
  if (tweening) {
    const k = Math.min(1, (now - twStart) / 900);
    const e = k * k * (3 - 2 * k);
    tState = twFrom + (twTo - twFrom) * e;
    slider.value = String(tState);
    if (k >= 1) tweening = false;
    dirty = true;
  } else if (playing) {
    tState += dt / 6;
    if (tState > 1) tState -= 1;
    slider.value = String(tState);
    dirty = true;
  }
  if (dirty) update();
  const q = camera.quaternion;
  for (let i = 0; i < NB; i++) bird3d[i].quaternion.copy(q);
  birdCur.quaternion.copy(q);
}
tick();
// @FIGURE_CODE_END

