// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (built exactly as listed) ─────────────────────────────────
   camera centre O       → SphereGeometry(0.11)                        black
   image plane fill      → PlaneGeometry(3.3,2.7) @ z=f=2.5   4% gray, no depthWrite
   image plane border    → 4 × BoxGeometry bars (thickness 0.045)      #333333
   bird silhouette       → THREE.Shape fill (white) + ribbon stroke mesh (black, fat)
   7 × 3D bird           → bird group, width 0.65, billboarded to camera
   8 × 3D velocity arrow → Cylinder(r .055) shaft + Cone(r .15,h .28)  #EE0000, equal length
   7 × green ray         → Cylinder(r .022) O→bird, #00CC00, rays 0–2 translucent
   7 × projected bird    → bird group in plane z=f+0.006, scale 0.65·f/Z
   6 × image arrow       → Cylinder(r .014)+Cone(r .05,h .12) #EE0000, shrinking
   vanishing point       → SphereGeometry(0.06) black @ f·(Vx/Vz,Vy/Vz)
   V direction ray       → Cylinder(r .022) O→V̂·7.0 #00CC00 (through VP)
   V ray arrow           → Cylinder(r .06)+Cone(r .17,h .40) #EE0000
   drag handle           → SphereGeometry(0.12) #FF7700 at ray tip
   current 3D bird       → bird group, orange stroke (slider / animation)
   current 3D step arrow → arrow #FF7700 (constant length = |V|·Δt)
   current image arrow   → arrow #FF7700 (shrinking projected step)
   labels                → addLabel: 'O', 'V' (3D arrow), 'V' (ray), 'Vanishing point'
──────────────────────────────────────────────────────────────────────────── */

const F = 2.5;
const DT = 0.5;
const NB = 7;
const P0 = new THREE.Vector3(-1.0, 1.2, 3.0);
const V0 = new THREE.Vector3(1.2, 0.35, 2.2);
const V = V0.clone();
const VMAG = V0.length();
const RAY_L = 7.0;
const BIRD_W = 0.65;
const TMAX = DT * (NB - 1);
const AOFF = 0.30;                        // gap between bird centre and arrow end
const PLN = { x0: -1.5, x1: 1.8, y0: -1.2, y1: 1.5 };
const COL = { green: 0x00cc00, red: 0xee0000, dark: 0x333333, orange: 0xff7700 };
const AX_UP = new THREE.Vector3(0, 1, 0);
const O_PT = new THREE.Vector3(0, 0, 0);
const HIDDEN = new THREE.Vector3(0, 1e5, 0);

const G3D = new THREE.Group();
const GPL = new THREE.Group();
scene.add(GPL);
scene.add(G3D);

/* ── generic helpers ──────────────────────────────────────────────────────── */
const segGeom = new THREE.CylinderGeometry(1, 1, 1, 10);
function setSegment(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-5) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  const r = mesh.userData.r || 1;
  mesh.scale.set(r, len, r);
  mesh.quaternion.setFromUnitVectors(AX_UP, dir.normalize());
}
function makeTube(r, color, opacity) {
  const m = new THREE.Mesh(segGeom, new THREE.MeshBasicMaterial({
    color, transparent: opacity < 1, opacity
  }));
  m.userData.r = r;
  return m;
}
function makeArrow(shaftR, headR, headL, color) {
  const mat = new THREE.MeshBasicMaterial({ color });
  const sg = new THREE.CylinderGeometry(shaftR, shaftR, 1, 12); sg.translate(0, 0.5, 0);
  const hg = new THREE.ConeGeometry(headR, headL, 16); hg.translate(0, headL / 2, 0);
  const shaft = new THREE.Mesh(sg, mat);
  const head = new THREE.Mesh(hg, mat);
  const g = new THREE.Group();
  g.add(shaft, head);
  g.userData = { shaft, head, headL };
  return g;
}
function setArrow(g, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-4) { g.visible = false; return; }
  g.visible = true;
  const { shaft, head, headL } = g.userData;
  const hl = Math.min(headL, len * 0.6);
  const hs = hl / headL;
  const sl = Math.max(len - hl, 1e-4);
  g.position.copy(a);
  g.quaternion.setFromUnitVectors(AX_UP, dir.clone().normalize());
  shaft.scale.set(hs, sl, hs);
  head.scale.setScalar(hs);
  head.position.set(0, sl, 0);
}

/* ── fat 2D outline ("stroke") as real geometry ───────────────────────────── */
function ribbonGeom(pts, w) {
  const h = w / 2, pos = [], idx = [];
  const n = pts.length;
  for (let i = 0; i < n; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    let dx = b.x - a.x, dy = b.y - a.y;
    const L = Math.hypot(dx, dy);
    if (L > 1e-6) {
      dx /= L; dy /= L;
      const nx = -dy * h, ny = dx * h;
      const base = pos.length / 3;
      pos.push(a.x + nx, a.y + ny, 0, a.x - nx, a.y - ny, 0,
        b.x + nx, b.y + ny, 0, b.x - nx, b.y - ny, 0);
      idx.push(base, base + 1, base + 2, base + 1, base + 3, base + 2);
    }
    // joint patch so convex corners stay closed
    const jb = pos.length / 3;
    pos.push(a.x - h, a.y - h, 0, a.x + h, a.y - h, 0, a.x + h, a.y + h, 0, a.x - h, a.y + h, 0);
    idx.push(jb, jb + 1, jb + 2, jb, jb + 2, jb + 3);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeBoundingBox();
  g.computeBoundingSphere();
  return g;
}

/* ── bird silhouette (gull, facing +X, 1 unit wide) ───────────────────────── */
function makeBirdShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.50, 0.32);
  s.quadraticCurveTo(-0.30, 0.02, -0.08, -0.10);   // left wing leading edge
  s.quadraticCurveTo(0.10, -0.16, 0.26, -0.06);    // body underside
  s.quadraticCurveTo(0.34, -0.02, 0.50, 0.02);     // beak
  s.quadraticCurveTo(0.36, 0.10, 0.30, 0.14);      // head / neck
  s.quadraticCurveTo(0.36, 0.30, 0.40, 0.44);      // right wing up
  s.quadraticCurveTo(0.26, 0.22, 0.10, 0.06);      // right wing trailing edge
  s.quadraticCurveTo(-0.08, 0.00, -0.24, 0.10);    // left wing trailing edge
