/* ── geometry update pass ─────────────────────────────────────────────────── */
let tState = 0;
let viewMode = '3D scene';

function P(t) { return new THREE.Vector3(P0.x + V.x * t, P0.y + V.y * t, P0.z + V.z * t); }
function proj(p) { return new THREE.Vector3(F * p.x / p.z, F * p.y / p.z, F + 0.006); }

const readoutEl = document.getElementById('readout');

function update() {
  const vhat = V.clone().normalize();
  const vp = new THREE.Vector3(F * V.x / V.z, F * V.y / V.z, F + 0.012);
  vpDot.position.copy(vp);

  const pts = [], qs = [], ss = [];
  for (let i = 0; i < NB; i++) {
    const p = P(i * DT); pts.push(p);
    qs.push(proj(p));
    ss.push(BIRD_W * F / p.z);
  }
  for (let i = 0; i < NB; i++) {
    bird3d[i].position.copy(pts[i]);
    setSegment(ray3d[i], O_PT, pts[i]);
    projBird[i].position.copy(qs[i]);
    projBird[i].scale.setScalar(ss[i]);
  }
  for (let i = 0; i < NB - 1; i++) {
    const u = new THREE.Vector3().subVectors(qs[i + 1], qs[i]);
    const L = u.length();
    if (L < 1e-4) { imgArrow[i].visible = false; continue; }
    u.divideScalar(L);
    const a = qs[i].clone().addScaledVector(u, 0.16 * ss[i]);
    const b = qs[i + 1].clone().addScaledVector(u, -0.20 * ss[i + 1]);
    if (new THREE.Vector3().subVectors(b, a).dot(u) < 0.01) { imgArrow[i].visible = false; continue; }
    a.z = F + 0.022; b.z = F + 0.022;
    setArrow(imgArrow[i], a, b);
  }
  for (let k = 0; k < arr3d.length; k++) {
    const i = k - 1;
    const a = P(i * DT).addScaledVector(vhat, AOFF);
    const b = P((i + 1) * DT).addScaledVector(vhat, -AOFF);
    setArrow(arr3d[k], a, b);
  }

  const far = vhat.clone().multiplyScalar(RAY_L);
  setSegment(dirRay, O_PT, far);
  handle.position.copy(far);
  setArrow(dirArrow,
    vhat.clone().multiplyScalar(RAY_L * 0.46),
    vhat.clone().multiplyScalar(RAY_L * 0.66));

  const tw = tState * TMAX;
  const pc = P(tw), pn = P(tw + DT);
  birdCur.position.copy(pc);
  setSegment(rayCur, O_PT, pc);
  setArrow(arrCur3d,
    pc.clone().addScaledVector(vhat, AOFF),
    pn.clone().addScaledVector(vhat, -AOFF));
