  setLabel(labVP, vp, true);

  const imgStep = Math.hypot(qn.x - qc.x, qn.y - qc.y);
  readoutEl.textContent =
    't        = ' + tw.toFixed(2) + '\n' +
    'depth Z  = ' + pc.z.toFixed(2) + '\n' +
    '3D step  = ' + (VMAG * DT).toFixed(3) + '   (constant)\n' +
    'img step = ' + imgStep.toFixed(3) + '\n' +
    'VP       = (' + vp.x.toFixed(2) + ', ' + vp.y.toFixed(2) + ')';
