  if (!dragging) return;
  ptr(e); dragRay.setFromCamera(dragPtr, camera);
  const sph = new THREE.Sphere(O_PT.clone(), RAY_L);
  const p = new THREE.Vector3();
  if (!dragRay.ray.intersectSphere(sph, p)) {
    dragRay.ray.closestPointToPoint(O_PT, p);
    if (p.length() < 1e-6) return;
    p.normalize().multiplyScalar(RAY_L);
  }
  setVfromPoint(p);
});
