let stepIdx = -1;
const stepTitleEl = document.getElementById('stepTitle');
const stepTextEl = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  playing = false;
  btnFly.textContent = '▶ Fly (constant V)';
  btnFly.classList.remove('active');
  setViewMode(s.state.viewMode);
  twFrom = tState; twTo = s.state.flightTime; twStart = performance.now(); tweening = true;
  stepTitleEl.textContent = (stepIdx + 1) + '/' + steps.length + '  ' + s.title;
  stepTextEl.textContent = s.narration;
