/* ── per-frame state loop (billboarding, time, framing zoom) ──────────────── */
let lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.06, (now - lastT) / 1000);
  lastT = now;
  let dirty = false;
  if (tweening) {
    const k = Math.min(1, (now - twStart) / 900);
    const e = k * k * (3 - 2 * k);
    tState = twFrom + (twTo - twFrom) * e;
    slider.value = String(tState);
    if (k >= 1) tweening = false;
    dirty = true;
  } else if (playing) {
    tState += dt / 6;
    if (tState > 1) tState -= 1;
    slider.value = String(tState);
    dirty = true;
  }
  if (dirty) update();
  // keep the authored framing crop even after scaffold re-fits (resize etc.)
  if (camera.isPerspectiveCamera && Math.abs(camera.zoom - viewZoom) > 1e-6) {
    camera.zoom = viewZoom;
    camera.updateProjectionMatrix();
  }
  const q = camera.quaternion;
  for (let i = 0; i < NB; i++) bird3d[i].quaternion.copy(q);
  birdCur.quaternion.copy(q);
}
tick();
